        { "Jan", "Feb", "Mar", "Apr", "May", "Jun",
          "Jul", "Aug", "Sep", "Oct", "Nov", "Dec" };
    const char *p = strstr(raw, "Date:");
    int mday = 0, year = 0, hh = 0, mm = 0, ss = 0;
    char mon[4] = {0};
    int mi = -1, i;

    if (p == NULL)
        return -1;
    p += 5;
    while (*p == ' ') p++;
    /* "Tue, 11 Aug 2026 01:05:02 GMT" */
    if (sscanf(p, "%*[^,], %d %3s %d %d:%d:%d",
               &mday, mon, &year, &hh, &mm, &ss) != 6)
        return -1;
    for (i = 0; i < 12; i++)
        if (strncmp(mon, months[i], 3) == 0) { mi = i; break; }
    if (mi < 0 || year < 2000 || year > 2100 || mday < 1 || mday > 31)
        return -1;

    struct tm tm;
    memset(&tm, 0, sizeof(tm));
    tm.tm_year = year - 1900;
    tm.tm_mon  = mi;
    tm.tm_mday = mday;
    tm.tm_hour = hh;
    tm.tm_min  = mm;
    tm.tm_sec  = ss;
    *out = mktime(&tm);   /* 无 TZ config → UTC */
    return 0;
}
