/* 2026-08-11：解析 HTTP Date 头（RFC 7231 IMF-fixdate，UTC）→ time_t。
 * board 无 TZ config，mktime 按 UTC 解释，直接得 UTC 时间戳。 */
static int parse_http_date(const char *raw, time_t *out)
{
    /* "Date: Tue, 11 Aug 2026 01:05:02 GMT" */
    const char *p = strstr(raw, "Date:");
    if (p == NULL) return -1;
    int mday = 0, year = 0, hh = 0, mi = 0, ss = 0;
    char mon[4] = {0};
    if (sscanf(p, "Date: %*s %d %3s %d %d:%d:%d GMT",
               &mday, mon, &year, &hh, &mi, &ss) != 6)
        return -1;
    static const char *months[] = {"Jan","Feb","Mar","Apr","May","Jun",
                                   "Jul","Aug","Sep","Oct","Nov","Dec"};
    int mon_i = -1;
    for (int i = 0; i < 12; i++)
        if (strncmp(mon, months[i], 3) == 0) { mon_i = i; break; }
    if (mon_i < 0 || year < 2000 || year > 2100 || mday < 1 || mday > 31)
        return -1;
    struct tm tm;
    memset(&tm, 0, sizeof(tm));
    tm.tm_year = year - 1900;
    tm.tm_mon  = mon_i;
    tm.tm_mday = mday;
    tm.tm_hour = hh;
    tm.tm_min  = mi;
    tm.tm_sec  = ss;
    *out = mktime(&tm);
    return 0;
}
```

