/* 2026-08-10 共享状态栏：Home 与子页（show_subpage）调用同一份代码，
 * 视觉完全一致（132px 全宽：左时钟+中文年月日 + 中天气 + 右 wifi/bt/battery）。
 * 输出指针由调用方提供：Home 传全局（clock_label/status_*），
 * 子页传 subpage_*（close_subpage 删除 overlay 前置空）。 */
void create_status_bar_ex(lv_obj_t *bar,
                          lv_obj_t **clock_out, lv_obj_t **date_out,
                          lv_obj_t **weather_out,
                          lv_obj_t **wifi_out, lv_obj_t **bt_out)
{
    /* bar is already created by caller, just populate it */
    lv_obj_set_flex_flow(bar, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(bar, LV_FLEX_ALIGN_SPACE_BETWEEN,
                          LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_left(bar, EDGE_PAD, 0);
    lv_obj_set_style_pad_right(bar, EDGE_PAD, 0);

    /* Left: clock + Chinese date (row) — 2026-08-11 时间右侧加中文年月日小字 */
    lv_obj_t *left = make_clean_cont(bar);
    lv_obj_set_size(left, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(left, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(left, LV_FLEX_ALIGN_END, LV_FLEX_ALIGN_CENTER,
                          LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_column(left, 10, 0);

    *clock_out = lv_label_create(left);
    lv_label_set_text(*clock_out, "00:00");
    lv_obj_set_style_text_color(*clock_out, lv_color_hex(COL_TEXT), 0);
    lv_obj_set_style_text_font(*clock_out, FONT_TITLE, 0);
    lv_obj_set_style_text_letter_space(*clock_out, 2, 0);

    /* 中文年月日：小字（FONT_BODY），时间右侧、底对齐 */
    *date_out = lv_label_create(left);
    lv_label_set_text(*date_out, "----年--月--日");
    lv_obj_set_style_text_color(*date_out, lv_color_hex(COL_SEC), 0);
    lv_obj_set_style_text_font(*date_out, FONT_BODY, 0);
    lv_obj_set_style_text_letter_space(*date_out, 1, 0);

    /* Center: weather — FONT_ICON, black text for readability */
    *weather_out = lv_label_create(bar);
    lv_label_set_text(*weather_out, "实时 21\xc2\xb0""C  |  65%");
    lv_obj_set_style_text_color(*weather_out, lv_color_hex(COL_TEXT), 0);
    lv_obj_set_style_text_font(*weather_out, FONT_ICON, 0);

