123	/* ── WebSocket frame send (masked, as client) ──────────────── */
124	
125	static int ws_send_text(node_ws_t* ws, const char* data, size_t len)
126	{
127	    if (!ws->connected)
128	        return -1;
129	
130	    uint8_t header[14];
131	    int hlen = 0;
132	    header[hlen++] = 0x81; /* FIN + text */
133	
134	    if (len < 126) {
135	        header[hlen++] = (uint8_t)(0x80 | len);
136	    } else if (len < 65536) {
137	        header[hlen++] = 0x80 | 126;
138	        header[hlen++] = (uint8_t)((len >> 8) & 0xFF);
139	        header[hlen++] = (uint8_t)(len & 0xFF);
140	    } else {
141	        header[hlen++] = 0x80 | 127;
142	        for (int i = 7; i >= 0; i--)
143	            header[hlen++] = (uint8_t)((len >> (i * 8)) & 0xFF);
144	    }
145	
146	    uint8_t mask[4];
147	    entropy_func(NULL, mask, 4);
148	    header[hlen++] = mask[0];
149	    header[hlen++] = mask[1];
150	    header[hlen++] = mask[2];
151	    header[hlen++] = mask[3];
152	
153	    if (raw_write(ws, header, hlen) < 0)
154	        return -1;
155	
156	    const uint8_t* src = (const uint8_t*)data;
157	    uint8_t chunk[256];
158	    for (size_t off = 0; off < len;) {
159	        size_t todo = len - off;
160	        if (todo > sizeof(chunk))
161	            todo = sizeof(chunk);
162	        for (size_t i = 0; i < todo; i++)
163	            chunk[i] = src[off + i] ^ mask[(off + i) & 3];
164	        if (raw_write(ws, chunk, todo) < 0)
165	            return -1;
166	        off += todo;
167	    }
168	    return 0;
169	}
