124	static int make_accept_key(const char* key, char* out, size_t out_size)
125	{
126	    char combined[256];
127	    int clen = snprintf(combined, sizeof(combined), "%s%s", key, WS_GUID);
128	    if (clen <= 0 || clen >= (int)sizeof(combined))
129	        return -1;
130	
131	    unsigned char sha[20];
132	    if (mbedtls_sha1((const unsigned char*)combined, (size_t)clen, sha) != 0)
133	        return -1;
134	
135	    size_t written = 0;
136	    if (mbedtls_base64_encode((unsigned char*)out, out_size, &written, sha,
137	            sizeof(sha))
138	        != 0)
139	        return -1;
140	    out[written] = '\0';
141	    return (int)written;
142	}
