146	 * Returns 0 on success; sends 101 response.
147	 */
148	static int do_ws_handshake(int fd, char* chat_id_out, size_t chat_id_size)
149	{
150	    char buf[1024];
151	    int total = 0;
152	
153	    /* Read until we see the end of headers */
154	    while (total < (int)sizeof(buf) - 1) {
155	        int n = recv(fd, buf + total, sizeof(buf) - 1 - total, 0);
156	        if (n <= 0)
157	            return -1;
158	        total += n;
159	        buf[total] = '\0';
160	        if (strstr(buf, "\r\n\r\n"))
161	            break;
162	    }
163	
164	    /* Extract Sec-WebSocket-Key */
165	    char* key_hdr = strcasestr(buf, "\r\nSec-WebSocket-Key: ");
166	    if (!key_hdr) {
167	        syslog(LOG_WARNING, "[%s] No Sec-WebSocket-Key\n", TAG);
168	        return -1;
169	    }
170	    key_hdr += 21;
171	    char* eol = strstr(key_hdr, "\r\n");
172	    if (!eol)
173	        return -1;
174	
175	    char ws_key[128] = { 0 };
176	    size_t klen = (size_t)(eol - key_hdr);
