static void create_ai_subpage(lv_obj_t *parent);

/* ── 2026-08-11 AI 子页 WS 接线 ──────────────────────────────────
 * 发送回调：取输入框文本 → dm_ai_ask()（后台线程连接 ai_agent WS
 * 28789 端口并等回复）→ 清空输入框、回复区显示 Thinking... */
static void ai_send_cb(lv_event_t *e)
{
    (void)e;
    if (!ai_ask_ta)
        return;
    const char *text = lv_textarea_get_text(ai_ask_ta);
    if (text == NULL || text[0] == '\0')
        return;
    if (dm_ai_ask(text) != 0)
        {
            if (ai_resp_lbl)
                lv_label_set_text(ai_resp_lbl, "AI busy...");
            return;
        }
    lv_textarea_set_text(ai_ask_ta, "");
    if (ai_resp_lbl)
        lv_label_set_text(ai_resp_lbl, "Thinking...");
}

/* 轮询 timer：worker 完成 → dm_ai_poll 取回复更新显示 */
static void ai_poll_cb(lv_timer_t *timer)
{
    (void)timer;
    char buf[AI_RESP_MAX];
    if (dm_ai_poll(buf, sizeof(buf)) && ai_resp_lbl)
        lv_label_set_text(ai_resp_lbl, buf);
}

