/* 轮询 timer：worker 完成 → dm_ai_poll 取回复更新显示 */
static void ai_poll_cb(lv_timer_t *timer)
{
    (void)timer;
    char buf[AI_RESP_MAX];
    if (dm_ai_poll(buf, sizeof(buf)))
        {
            if (ai_resp_lbl)
                lv_label_set_text(ai_resp_lbl, buf);
            if (ai_status_lbl)
                lv_label_set_text(ai_status_lbl, "Ready to help");
        }
    else if (dm_ai_busy() && ai_status_lbl)
        {
            lv_label_set_text(ai_status_lbl, "Thinking...");
        }
}

